using MassiveArmy.Industrial;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.Rendering;
using UnityEngine.UIElements;
namespace MassiveArmy.Planetary {
    public sealed partial class PlanetDevelopment {
        InventorySlotUi inventorySlotUi;VisualElement groundLootPanel;long openedGroundLoot;Mesh groundLootMesh;Material groundLootMaterial;readonly Matrix4x4[] groundLootMatrices=new Matrix4x4[256];
        internal bool GroundLootOpen=>groundLootPanel?.style.display==DisplayStyle.Flex;
        internal VisualElement InventoryWindowSurface=>IndustrialMenuOpen?industry?.MenuSurface:GroundLootOpen?groundLootPanel:personalHud?.InventorySurface;
        internal void AttachInventoryUi(VisualElement parent){if(!IsSurvival)return;inventorySlotUi?.Dispose();inventorySlotUi=new InventorySlotUi(this,parent);groundLootPanel?.RemoveFromHierarchy();groundLootPanel=new VisualElement{name="ground-loot-panel"};groundLootPanel.style.position=Position.Absolute;groundLootPanel.style.left=Length.Percent(8);groundLootPanel.style.top=Length.Percent(10);groundLootPanel.style.width=Length.Percent(84);groundLootPanel.style.height=Length.Percent(76);groundLootPanel.style.backgroundColor=new Color(.025f,.04f,.055f,.98f);groundLootPanel.style.paddingLeft=groundLootPanel.style.paddingRight=16;groundLootPanel.style.paddingTop=groundLootPanel.style.paddingBottom=16;groundLootPanel.style.display=DisplayStyle.None;groundLootPanel.RegisterCallback<PointerDownEvent>(e=>e.StopPropagation());parent.Add(groundLootPanel);}
        internal void BindInventoryHotbar(Button[] buttons,VisualElement surface){if(inventorySlotUi==null)return;for(int i=0;i<buttons.Length;i++)inventorySlotUi.Bind(buttons[i],new InventoryAddress{slot=i},surface);}
        internal void BuildBackpackSlots(VisualElement parent){inventorySlotUi?.AddGrid(parent,new InventoryAddress(),10,30,"BACKPACK");inventorySlotUi?.AddBulk(parent,new InventoryAddress(),"CARRIED BULK MATERIAL");inventorySlotUi?.AddDropZone(parent);var info=new Label("Drag stacks to move, swap or merge. Right-drag moves half. Equip placeables from the hotbar to build.");info.style.whiteSpace=WhiteSpace.Normal;parent.Add(info);}
        internal void BuildMachineSlots(VisualElement parent,IndustrialMachine machine){
            if(inventorySlotUi==null)return;parent.Clear();var row=new VisualElement();row.style.flexDirection=FlexDirection.Row;parent.Add(row);var carried=new VisualElement();carried.style.width=Length.Percent(50);carried.style.paddingRight=10;row.Add(carried);var storage=new VisualElement();storage.style.width=Length.Percent(50);row.Add(storage);
            inventorySlotUi.AddGrid(carried,new InventoryAddress(),10,30,"YOUR BACKPACK · HOTBAR BELOW");inventorySlotUi.AddBulk(carried,new InventoryAddress(),"CARRIED PAY DIRT");inventorySlotUi.AddDropZone(carried);
            inventorySlotUi.AddGrid(storage,new InventoryAddress{entity=machine.id,section="input"},0,18,machine.Definition.storage?"STORAGE / PAYLOAD":"MACHINE INPUT");if(!machine.Definition.storage)inventorySlotUi.AddGrid(storage,new InventoryAddress{entity=machine.id,section="output"},0,12,"OUTPUT · TAKE ONLY");if(machine.Definition.storage||machine.definition=="sluice")inventorySlotUi.AddBulk(storage,new InventoryAddress{entity=machine.id,section="input"},"BULK PAYLOAD");if(machine.definition=="sluice"||machine.definition=="water-reservoir")inventorySlotUi.AddReservoir(storage,machine.id);
        }
        internal string DropInventoryStack(InventoryAddress source,long count,string expected){
            if(LocalPlayerDead||IndustrialAuthority==null)return "Cannot drop items now";var forward=view.transform.forward;var eye=view.transform.position;var render=eye+forward*1.25f;if(Physics.Raycast(eye,forward,out var wall,1.25f,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore))render=wall.point-forward*.2f;var body=RenderToBody(render);var up=player.AttachedToShip&&HasRespawnCarrier?spacecraft.Rotation*Vector3.up:PlanetPrecisionPolicy.Direction(body);
            if(Physics.Raycast(render,-up,out var floor,3,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore))body=RenderToBody(floor.point)+new Double3(up)*.08;else body-=new Double3(up)*.8;
            var canonical=RespawnPose(body);if(player.AttachedToShip&&HasRespawnCarrier){var local=spacecraft.BodyToLocal(body);canonical.frame=1;canonical.x=local.x;canonical.y=local.y;canonical.z=local.z;}return IndustrialAuthority.DropInventory(1,source,count,canonical,RespawnPose(body),expected);
        }
        DroppedInventory AimedGroundLoot(){if(IndustrialAuthority==null||LocalPlayerDead)return null;var eye=view.transform.position;var direction=view.transform.forward;float nearest=4;if(Physics.Raycast(eye,direction,out var hit,4,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore))nearest=hit.distance+.1f;DroppedInventory best=null;foreach(var drop in IndustrialAuthority.World.droppedItems){if(!TryResolveRespawnPose(drop.pose,out var position,out _))continue;var delta=RenderBodyPosition(position)+Vector3.up*.2f-eye;float along=Vector3.Dot(delta,direction);if(along<0||along>nearest||(delta-direction*along).sqrMagnitude>.65f*.65f)continue;nearest=along;best=drop;}return best;}
        internal string GroundLootPrompt=>AimedGroundLoot()!=null?"F · OPEN DROPPED ITEMS":"";
        internal bool InteractGroundLoot(){var drop=AimedGroundLoot();if(drop==null||groundLootPanel==null)return false;personalHud?.Close();CloseIndustryMenu();CloseRespawnPointMenu();CancelRespawnPlacement();openedGroundLoot=drop.id;groundLootPanel.Clear();groundLootPanel.Add(new Label("DROPPED ITEMS"));groundLootPanel.Add(new Button(CloseGroundLoot){text="CLOSE [ESC]"});var row=new VisualElement();row.style.flexDirection=FlexDirection.Row;row.style.flexGrow=1;groundLootPanel.Add(row);var left=new ScrollView();left.style.width=Length.Percent(50);row.Add(left);var right=new ScrollView();right.style.width=Length.Percent(50);row.Add(right);inventorySlotUi.AddGrid(left,new InventoryAddress(),10,30,"YOUR BACKPACK · HOTBAR BELOW");inventorySlotUi.AddBulk(left,new InventoryAddress(),"CARRIED BULK");inventorySlotUi.AddGrid(right,new InventoryAddress{entity=drop.id,section="ground"},0,12,"GROUND LOOT");inventorySlotUi.AddBulk(right,new InventoryAddress{entity=drop.id,section="ground"},"DROPPED PAY DIRT");groundLootPanel.style.display=DisplayStyle.Flex;groundLootPanel.BringToFront();SetPersonalCursor(true);return true;}
        internal void CloseGroundLoot(){if(groundLootPanel!=null)groundLootPanel.style.display=DisplayStyle.None;openedGroundLoot=0;SetPersonalCursor(false);}
        void RenderGroundLoot(){if(!IsSurvival||IndustrialAuthority==null)return;if(GroundLootOpen&&(LocalPlayerDead||IndustrialAuthority.World.Dropped(openedGroundLoot)==null||Keyboard.current?.escapeKey.wasPressedThisFrame==true))CloseGroundLoot();inventorySlotUi?.Refresh();int count=0;foreach(var drop in IndustrialAuthority.World.droppedItems){if(!TryResolveRespawnPose(drop.pose,out var position,out var rotation))continue;var at=RenderBodyPosition(position);if((at-view.transform.position).sqrMagnitude>600*600)continue;groundLootMatrices[count++]=Matrix4x4.TRS(at,rotation,Vector3.one);}
            if(count==0)return;if(groundLootMesh==null){var g=new ModularGeometry();g.Box(new Vector3(0,.16f,0),new Vector3(.38f,.32f,.32f),new Color(.3f,.35f,.25f,0));g.Box(new Vector3(0,.17f,0),new Vector3(.045f,.34f,.34f),new Color(.8f,.54f,.15f,0));groundLootMesh=g.Build("Shared dropped supplies mesh");groundLootMaterial=ColonyPrototypeLibrary.Material("Dropped supplies");}Graphics.RenderMeshInstanced(new RenderParams(groundLootMaterial){camera=view,worldBounds=new Bounds(view.transform.position,Vector3.one*1400),shadowCastingMode=ShadowCastingMode.Off},groundLootMesh,0,groundLootMatrices,count);
        }
        void DisposeInventoryUi(){inventorySlotUi?.Dispose();groundLootPanel?.RemoveFromHierarchy();ArmyLifetime.Destroy(groundLootMesh);ArmyLifetime.Destroy(groundLootMaterial);}
    }
